/** Controlled update of the three audited old posts; only original body is replaced. */
add_action('init',function(){
    $flag='bmd_support_apps_oct28_v1';
    if(get_option($flag)==='applied')return;
    $result=array();
    foreach(bmd_oct28_support_and_apps_rewrites() as $slug=>$d){
        $p=get_page_by_path($slug,OBJECT,'post');
        if(!$p || (int)$p->ID!==(int)$d['id'] || $p->post_status!=='publish'){
            $result[$slug]='missing-or-not-matching';continue;
        }
        $backup='_bmd_support_apps_original_oct28';
        if(metadata_exists('post',$p->ID,$backup)){$result[$slug]='already-backed-up';continue;}
        $old=(string)$p->post_content;
        if(strlen($old)<1900||strlen($old)>110000||stripos(wp_strip_all_tags($old),$d['needle'])===false){
            $result[$slug]='original-guard-failed';continue;
        }
        if(!add_post_meta($p->ID,$backup,$old,true)){$result[$slug]='backup-failed';continue;}
        $saved=wp_update_post(array('ID'=>$p->ID,'post_title'=>$d['title'],'post_content'=>$d['body']),true);
        if(is_wp_error($saved)||!$saved){delete_post_meta($p->ID,$backup);$result[$slug]='update-failed';continue;}
        update_post_meta($p->ID,'rank_math_title',$d['title'].' | BMD');
        update_post_meta($p->ID,'rank_math_description',$d['meta']);
        clean_post_cache($p->ID);
        $result[$slug]='applied';
    }
    $errors=array_filter($result,function($v){return !in_array($v,array('applied','already-backed-up'),true);});
    update_option($flag,$errors?wp_json_encode($result):'applied',false);
},35);

add_filter('rank_math/frontend/title',function($title){
    if(is_admin()||!is_singular('post'))return $title;
    $slug=(string)get_post_field('post_name',get_queried_object_id());
    $all=bmd_oct28_support_and_apps_rewrites();
    if(!isset($all[$slug])||!metadata_exists('post',get_queried_object_id(),'_bmd_support_apps_original_oct28'))return $title;
    return $all[$slug]['title'].' | BMD';
},87);
add_filter('rank_math/frontend/description',function($description){
    if(is_admin()||!is_singular('post'))return $description;
    $slug=(string)get_post_field('post_name',get_queried_object_id());
    $all=bmd_oct28_support_and_apps_rewrites();
    if(!isset($all[$slug])||!metadata_exists('post',get_queried_object_id(),'_bmd_support_apps_original_oct28'))return $description;
    return $all[$slug]['meta'];
},87);

